inj() { tmux send-keys -t "=$T:builder-$1" "campaign-exec: printf '\342\226\240 last status: %s%s %s\n' $2 '$3'" Enter; for i in $(seq 50); do tmux capture-pane -p -t "=$T:builder-$1" | grep -q "^■ last status: [0-9]* $3" && return; sleep 0.1; done; exit 1; }
scan() { $C watch --interval 0.5 --backstop 1 --no-nudge $P >/dev/null; }
inj 2 '4 29' 'Too Many Requests'; scan; echo "one 429 on builder-2: $(errs)"; eq "$(errs)" "1 builder-2"
scan; scan; echo "same text, two more scans: $(errs)"; eq "$(errs)" "1 builder-2"
inj 3 '4 29' 'Too Many Requests'; inj 4 '5 03' 'Service Unavailable'; scan; echo "builder-3 429, builder-4 503: $(errs)"; eq "$(errs)" "3 builder-2 builder-3 builder-4"

