age; dec builder low; echo "next interval: $(dj)"; eq "$(tgt)" "1"
age; dec builder low; echo "at the floor: $(dj)"; eq "$(tgt)" "1"
eq "$($C status $P | grep -cE '^builder-[234] .* alive')" "3"; echo "builders 2-4 alive: nothing killed"
for i in 2 3 4; do printf '{"number": 3%s, "state": "MERGED", "headRefOid": "%s", "isDraft": false, "labels": [], "closingIssuesReferences": []}\n' $i $(git -C {state_dir}/../origin.git rev-parse main) > $G/pr-view-3$i.json; done
for i in 2 3; do echo "done: #$i #3$i $(git -C {state_dir}/../origin.git rev-parse main)" >> $S/status/builder-$i.status; done
dec builder low; echo "builder-2,3 done, builder-4 busy: $(dj)"; eq "$(dj)" "T=1 deferred:b#5:target"
echo "done: #4 #34 $(git -C {state_dir}/../origin.git rev-parse main)" >> $S/status/builder-4.status
dec builder low; echo "all drained: $(dj)"; eq "$(dj)" "T=1 admit:b#5:-"

